import { Component, Input, Output, EventEmitter } from '@angular/core';
import { Email } from '../../../../core/models/email.model';

@Component({
  selector: 'app-email-card',
  templateUrl: './email-card.component.html',
  styleUrls: ['./email-card.component.scss']
})
export class EmailCardComponent {
  @Input() email!: Email;
  @Input() isSelected = false;
  @Output() selected = new EventEmitter<Email>();
  @Output() starred = new EventEmitter<Email>();

  getInitials(name: string): string {
    return name.split(' ').map(n => n[0]).join('').slice(0, 2).toUpperCase();
  }

  onSelect(): void {
    this.selected.emit(this.email);
  }

  onStar(event: Event): void {
    event.stopPropagation();
    this.starred.emit(this.email);
  }
}
<div
  class="email-card"
  [class.email-card--selected]="isSelected"
  [class.email-card--unread]="!email.isRead"
  (click)="onSelect()">

  <!-- Unread dot -->
  <span class="email-card__unread-dot" *ngIf="!email.isRead"></span>

  <!-- Avatar -->
  <div class="email-card__avatar" [style.background]="email.avatarColor">
    {{ getInitials(email.sender) }}
  </div>

  <!-- Content -->
  <div class="email-card__content">
    <div class="email-card__top">
      <span class="email-card__sender">{{ email.sender }}</span>
      <span class="email-card__time">{{ email.timestamp | relativeTime }}</span>
    </div>

    <p class="email-card__subject">{{ email.subject }}</p>
    <p class="email-card__preview">{{ email.preview }}</p>

    <!-- Footer: tags + attachment indicator -->
    <div class="email-card__footer" *ngIf="email.tags.length > 0 || email.attachments.length > 0">
      <span class="email-card__tag" *ngFor="let tag of email.tags">{{ tag }}</span>
      <span class="email-card__attachment" *ngIf="email.attachments.length > 0">
        <svg width="12" height="12" viewBox="0 0 12 12" fill="none">
          <path d="M9.5 5.5L5 10a3 3 0 01-4.24-4.24l5-5a2 2 0 012.83 2.83L4.34 7.83a1 1 0 01-1.41-1.41L7.5 2"
            stroke="currentColor" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round"/>
        </svg>
        {{ email.attachments.length }}
      </span>
    </div>
  </div>

  <!-- Star button -->
  <button class="email-card__star" (click)="onStar($event)" [class.email-card__star--active]="email.isStarred">
    <svg width="14" height="14" viewBox="0 0 14 14" fill="none">
      <path d="M7 1l1.545 3.13L12 4.635l-2.5 2.436.59 3.44L7 8.9l-3.09 1.615.59-3.44L2 4.635l3.455-.505L7 1z"
        [attr.fill]="email.isStarred ? '#f59e0b' : 'none'"
        [attr.stroke]="email.isStarred ? '#f59e0b' : 'currentColor'"
        stroke-width="1.2" stroke-linejoin="round"/>
    </svg>
  </button>
</div>
